mapper.select:
SELECT h.history_id, h.target_table AS target, h.target_key, h.field_name AS field, h.before_value, h.after_value, h.change_reason, u.email AS changed_by, h.changed_at AT TIME ZONE 'Asia/Seoul' AS changed_at FROM criteria_change_history h LEFT JOIN users u ON u.user_id = h.changed_by AND u.deleted_at IS NULL
(h.changed_at < #{lastChangedAt} OR (h.changed_at = #{lastChangedAt} AND h.history_id < #{lastId}))
ORDER BY h.changed_at DESC, h.history_id DESC LIMIT #{limit}
